    return cur

def text(x):
    if x is None:
        return ''
    if isinstance(x, (list, tuple, set)):
        return ' '.join([text(i) for i in x])
    if isinstance(x, dict):
        return ' '.join([text(k) + ' ' + text(v) for k, v in x.items()])
    return str(x).lower()

def needverb(tt):
    s = text(tt)
    if 'cool' in s:
        return 'cool'
    if 'heat' in s:
        return 'heat'
    if 'clean' in s:
        return 'clean'
    if 'slice' in s:
        return 'slice'
    return ''

def hook(ctx, nb):
    tt = getv(ctx, 'task.task_type', '')
    target = text(getv(ctx, 'task.target_type', ''))
    dest = text(getv(ctx, 'task.destination_type', ''))
    verb = needverb(tt)
    if not verb:
        nb['transformed'] = True
    act = text(getv(ctx, 'action.final_action', getv(ctx, 'action.normalized', getv(ctx, 'action.raw', ''))))
    obs = text(ctx.get('observation', ''))
    inv = text(getv(ctx, 'world.inventory', ''))
    pc = getv(ctx, 'world.placed_count', nb.get('placed_count', 0))
    try:
        pc = int(pc)
    except Exception:
        pc = 0
    if pc > nb.get('placed_count', 0):
        nb['placed_count'] = pc
    locs = getv(ctx, 'world.placed_locations', [])
    if isinstance(locs, (list, tuple, set)):
        locs_text = ' '.join([text(i) for i in locs])
    else:
        locs_text = text(locs)
    if locs_text and locs_text not in nb.get('placed_locations', ''):
        nb['placed_locations'] = nb.get('placed_locations', '') + ' ' + locs_text
    if verb and target and act.startswith(verb + ' ') and target in act and 'nothing happens' not in obs:
        nb['transformed'] = True
    if target and act.startswith('put ') and target in act and 'you put' in obs:
        if not verb or nb.get('transformed'):
            nb['placed_count'] = nb.get('placed_count', 0) + 1
            nb['last_put_dest'] = dest
            nb['last_put_action'] = act
    carrying = bool(target and target in inv and 'nothing' not in inv and 'not carrying' not in inv)
    wrong = bool(inv and 'nothing' not in inv and 'not carrying' not in inv and target and target not in inv)
    take_here = bool(target and any(a.startswith('take ') and target in a for a in ctx.get('admissible', [])))
    put_here = bool(target and dest and any(a.startswith('put ') and target in a and dest in a for a in ctx.get('admissible', [])))
    if wrong:
        stage = 'wrong_inventory'
    elif carrying:
        if verb and not nb.get('transformed'):
            stage = 'transform'
        elif put_here:
            stage = 'put_target'
        else:
            stage = 'go_destination'
    elif take_here or getv(ctx, 'world.target_found', False) or getv(ctx, 'world.target_location', ''):
        stage = 'take_target'
    else:
        stage = 'find_target'
    nb['stage'] = stage
    nb['target_type'] = target
    nb['destination_type'] = dest
    nb['task_type'] = tt
    nb['required_verb'] = verb
    return None

