def hook(ctx, nb):
    stage = nb.get('stage', '')
    target = nb.get('target_type') or text(getv(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or text(getv(ctx, 'task.destination_type', ''))
    verb = nb.get('required_verb') or needverb(getv(ctx, 'task.task_type', ''))
    msg = ''
    if stage == 'wrong_inventory':
        msg = 'Inventory does not match the requested target type. Do not place the wrong item at the destination; recover by setting it aside if needed and searching for the target.'
    elif stage == 'take_target' and target:
        msg = 'A requested ' + target + ' is available here. Take the target now instead of continuing to search or examine unrelated objects.'
    elif stage == 'transform' and target and verb:
        place = 'sinkbasin'
        if verb == 'heat':
            place = 'microwave'
        if verb == 'cool':
            place = 'fridge'
        if verb == 'slice':
            place = 'knife'
        msg = 'Carry the ' + target + ' to a ' + place + ' and use the admissible ' + verb + ' action before placing it.'
    elif stage == 'put_target' and target and dest:
        msg = 'You are at the requested ' + dest + ' with the ' + target + '. Use the admissible put action for this destination now.'
    elif stage == 'go_destination' and target and dest:
        msg = 'Carry the ' + target + ' to a ' + dest + ' and put it there; do not put it on other receptacles.'
    elif stage == 'find_target' and target and (getv(ctx, 'predicates.same_action_repeated', False) or getv(ctx, 'predicates.same_observation_repeated', False) or getv(ctx, 'predicates.remaining_steps_low', False)):
        msg = 'Search unopened or unvisited containers for the ' + target + '; when its take action appears, take it immediately.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

